fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Both m and n are strictly positive on entry.
    // We use the subtraction-based Euclidean algorithm:
    //   gcd(m, n) = gcd(m - n, n) if m > n
    //             = gcd(m, n - m) if n > m
    //
    // Loop invariant:
    //   1. m > 0 and n > 0
    //   2. gcd(m, n) is unchanged from the original inputs
    //   3. The sum (m + n) strictly decreases each iteration
    //
    // The loop terminates when m == n, at which point
    // m (or n) is the greatest common divisor.

    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }

    // When the loop exits, m == n == gcd(original_m, original_n)
    m
}

